(()=>{
'use strict';
if(window.__MATCHSIK_ADMIN_TEACHERS_V281__)return;window.__MATCHSIK_ADMIN_TEACHERS_V281__=true;
const cfg=()=>window.MATCHSIK_CONFIG||window.matchsikConfig||{};
const base=()=>String(cfg().apiBaseUrl||'').replace(/\/$/,'');
const key=()=>String(cfg().supabasePublishableKey||cfg().publishableKey||'').trim();
const token=()=>sessionStorage.getItem('matchsik_admin_token')||'';
const esc=(value)=>String(value??'').replace(/[&<>'"]/g,(ch)=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[ch]));
const apiUrl=(path)=>base()+'/api/'+String(path||'').replace(/^\/+/, '').replace(/^api\//,'');
let data={items:[],catalog:[]};let selectedId='';
async function api(path,options={}){const response=await fetch(apiUrl(path),{method:options.method||'GET',headers:{'content-type':'application/json',...(key()?{apikey:key()}:{}),...(token()?{authorization:`Bearer ${token()}`}:{})},body:options.body,cache:'no-store'});const payload=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(`${payload.error||'요청을 처리하지 못했습니다.'}${payload.requestId?` · 문의번호 ${payload.requestId}`:''}`);error.status=response.status;throw error}return payload}
function close(){document.querySelector('.m28-admin-overlay')?.remove()}
function blankTeacher(){return {id:'',name:'',role:'자격증 전문 강사',tags:[],assignments:[],active:true,completed_lessons:0,sort_order:100,login:null}}
function selected(){if(selectedId==='__new__')return blankTeacher();return data.items.find((item)=>item.id===selectedId)||data.items[0]||null}
function isSelected(teacher,code,course){return (teacher.assignments||[]).some((item)=>item.certificateCode===code&&(item.courses||[]).includes(course))}
function assignmentsHtml(teacher){return `<div class="m28-catalog-toolbar"><input class="m28-catalog-search" data-admin-catalog-search placeholder="자격증 검색"><span class="t28-status-pill">정확히 선택한 과정만 신청 가능</span></div><div class="m28-assignment-grid">${data.catalog.map((cert)=>{const allowed=Array.isArray(cert.allowed_courses)?cert.allowed_courses:[];return `<article class="m28-assignment-card" data-admin-catalog-card data-search="${esc(`${cert.name} ${cert.category} ${cert.group_name}`.toLowerCase())}"><div class="m28-assignment-card-head"><div><h4>${esc(cert.name)}</h4><small>${esc(cert.category)} · ${esc(cert.group_name)}</small></div>${cert.code==='electric-craftsman'?'<span class="m28-written-only-badge">필기 전용</span>':''}</div><div class="m28-course-options">${['필기','실기','필기+실기'].map((course)=>`<label class="m28-course-option ${allowed.includes(course)?'':'disabled'}"><input type="checkbox" data-admin-assignment data-certificate-code="${esc(cert.code)}" value="${course}" ${isSelected(teacher,cert.code,course)?'checked':''} ${allowed.includes(course)?'':'disabled'}><span>${course}</span></label>`).join('')}</div></article>`}).join('')}</div>`}
function form(teacher){if(!teacher)return '<div class="m28-editor">등록된 강사가 없습니다.</div>';return `<form class="m28-editor" data-admin-teacher-form data-old-id="${esc(teacher.id)}"><div class="m28-form-grid"><div class="m28-field"><label>강사 ID</label><input name="id" value="${esc(teacher.id)}" required></div><div class="m28-field"><label>강사명</label><input name="name" value="${esc(teacher.name||'')}" required></div><div class="m28-field full"><label>전문 역할</label><input name="role" value="${esc(teacher.role||'')}"></div><div class="m28-field full"><label>경력 요약</label><textarea name="careerSummary">${esc(teacher.career_summary||'')}</textarea></div><div class="m28-field full"><label>수업 방식</label><textarea name="teachingStyle">${esc(teacher.teaching_style||'')}</textarea></div><div class="m28-field"><label>태그 · 쉼표 구분</label><input name="tags" value="${esc((teacher.tags||[]).join(', '))}"></div><div class="m28-field"><label>프로필 이미지 URL</label><input name="profileImageUrl" value="${esc(teacher.profile_image_url||'')}"></div><div class="m28-field"><label>완료 수업 횟수</label><input name="completedLessons" type="number" min="0" value="${esc(teacher.completed_lessons||0)}"></div><div class="m28-field"><label>정렬 순서</label><input name="sortOrder" type="number" value="${esc(teacher.sort_order||100)}"></div><label class="m28-course-option"><input name="active" type="checkbox" ${teacher.active!==false?'checked':''}><span>수강생 신청 화면 공개</span></label><div class="m28-field"><label>연결 로그인</label><input value="${esc(teacher.login?.email||'미연결')} · ${teacher.login?.active===false?'로그인 차단':'로그인 가능'}" disabled></div></div><div style="margin-top:22px"><h3>참여 자격증과 과정</h3><p style="color:#687d77;font-size:13px">강사 본인과 관리자 모두 수정할 수 있습니다. 전기기능사는 필기만 운영됩니다.</p>${assignmentsHtml(teacher)}</div><div class="m28-save-bar"><button class="t28-save" type="submit">강사 정보 저장</button></div></form>`}
function render(){const overlay=document.querySelector('.m28-admin-overlay');if(!overlay)return;const teacher=selected();overlay.querySelector('[data-admin-teacher-nav]').innerHTML=`<button type="button" data-admin-new-teacher class="${selectedId==='__new__'?'active':''}"><b>＋ 새 강사 프로필</b><br><small>Auth 계정 연결 전 프로필 생성</small></button>`+data.items.map((item)=>`<button type="button" data-admin-select-teacher="${esc(item.id)}" class="${item.id===(teacher?.id||'')&&selectedId!=='__new__'?'active':''}"><b>${esc(item.name||item.id)}</b><br><small>${esc(item.id)} · ${esc(item.login?.email||'계정 미연결')}</small></button>`).join('');overlay.querySelector('[data-admin-teacher-editor]').innerHTML=form(teacher);bind()}
function bind(){const overlay=document.querySelector('.m28-admin-overlay');const search=overlay?.querySelector('[data-admin-catalog-search]');search?.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();overlay.querySelectorAll('[data-admin-catalog-card]').forEach((card)=>card.hidden=q&&!card.dataset.search.includes(q))});overlay?.querySelector('[data-admin-teacher-form]')?.addEventListener('submit',save)}
function collectAssignments(form){const map=new Map();form.querySelectorAll('[data-admin-assignment]:checked').forEach((input)=>{const code=input.dataset.certificateCode;if(!map.has(code))map.set(code,[]);map.get(code).push(input.value)});return [...map].map(([certificateCode,courses])=>({certificateCode,courses}))}
async function save(event){event.preventDefault();const form=event.currentTarget,button=event.submitter,fd=new FormData(form);button.disabled=true;button.textContent='저장 중…';try{const payload={profile:{id:String(fd.get('id')||'').trim(),name:String(fd.get('name')||'').trim(),role:fd.get('role'),careerSummary:fd.get('careerSummary'),teachingStyle:fd.get('teachingStyle'),tags:String(fd.get('tags')||'').split(',').map((x)=>x.trim()).filter(Boolean),profileImageUrl:fd.get('profileImageUrl'),completedLessons:Number(fd.get('completedLessons')||0),sortOrder:Number(fd.get('sortOrder')||100),active:fd.get('active')==='on'},assignments:collectAssignments(form)};const isNew=!form.dataset.oldId;const result=await api(isNew?'/admin/teachers':`/admin/teachers/${encodeURIComponent(form.dataset.oldId)}`,{method:isNew?'POST':'PUT',body:JSON.stringify(payload)});data.items=result.items||data.items;selectedId=result.teacher?.id||payload.profile.id;render();alert('강사 정보와 참여 자격증을 저장했습니다.')}catch(error){alert(error.message)}finally{button.disabled=false;button.textContent='강사 정보 저장'}}
async function open(){if(!token()){alert('관리자 로그인 후 이용해 주세요.');return}close();const overlay=document.createElement('div');overlay.className='m28-admin-overlay';overlay.innerHTML=`<section class="m28-admin-panel"><header class="m28-admin-panel-head"><div><h2>강사 프로필·참여 자격증 관리</h2><p style="margin:5px 0 0;color:#687d77">저장 실패 원인을 분리하고, ID 대소문자와 자격증별 과정 배정을 함께 관리합니다.</p></div><button class="m28-admin-close" type="button" data-admin-overlay-close>×</button></header><div class="m28-teacher-list"><nav class="m28-teacher-nav" data-admin-teacher-nav></nav><div data-admin-teacher-editor><div class="m28-editor">강사 목록을 불러오는 중입니다.</div></div></div></section>`;document.body.appendChild(overlay);document.body.style.overflow='hidden';try{data=await api('/admin/teachers');selectedId=data.items?.[0]?.id||'';render()}catch(error){overlay.querySelector('[data-admin-teacher-editor]').innerHTML=`<div class="m28-login-error">${esc(error.message)}</div>`}}
function launch(){if(document.querySelector('[data-m28-admin-launch]'))return;const button=document.createElement('button');button.className='m28-admin-launch';button.type='button';button.dataset.m28AdminLaunch='1';button.textContent='강사 설정 v28';button.addEventListener('click',open);document.body.appendChild(button)}
document.addEventListener('click',(event)=>{if(event.target.closest('[data-admin-overlay-close]')||event.target.classList.contains('m28-admin-overlay')){document.body.style.overflow='';close();return}const create=event.target.closest('[data-admin-new-teacher]');if(create){selectedId='__new__';render();return}const select=event.target.closest('[data-admin-select-teacher]');if(select){selectedId=select.dataset.adminSelectTeacher;render()}});
new MutationObserver(()=>{if(token())launch()}).observe(document.documentElement,{subtree:true,childList:true});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{if(token())launch()});else if(token())launch();
window.MATCHSIK_V28_ADMIN_TEACHERS={open};
})();
